import 'package:flutter/material.dart';import '../domain/models/contact.dart';import '../data/contact_group_service.dart';import '../data/contact_service.dart';class ContactGroupsScreen extends StatefulWidget {  final ContactService contactService;  final ContactGroupService groupService;  final List<Contact> contacts;  const ContactGroupsScreen({    super.key,    required this.contactService,    required this.groupService,    required this.contacts,  });  @override  State<ContactGroupsScreen> createState() => _ContactGroupsScreenState();}class _ContactGroupsScreenState extends State<ContactGroupsScreen> {  late List<ContactGroupModel> _groups;  @override  void initState() {    super.initState();    _groups = widget.groupService.getAll();  }  void _refresh() {    setState(() {      _groups = widget.groupService.getAll();    });  }  Future<void> _createGroup() async {    final nameController = TextEditingController();    Color selectedColor = Colors.blue;    await showDialog(      context: context,      builder: (ctx) => StatefulBuilder(        builder: (ctx, setDialogState) => AlertDialog(          title: const Text('Create Group'),          content: Column(            mainAxisSize: MainAxisSize.min,            children: [              TextField(                controller: nameController,                decoration: const InputDecoration(                  labelText: 'Group Name',                  hintText: 'e.g., Family, Team, Rescue',                ),              ),              const SizedBox(height: 16),              const Text('Color:'),              const SizedBox(height: 8),              Wrap(                spacing: 8,                children: [                  Colors.blue,                  Colors.green,                  Colors.red,                  Colors.purple,                  Colors.orange,                  Colors.teal,                  Colors.pink,                  Colors.indigo,                ].map((color) {                  return GestureDetector(                    onTap: () => setDialogState(() => selectedColor = color),                    child: Container(                      width: 32,                      height: 32,                      decoration: BoxDecoration(                        color: color,                        shape: BoxShape.circle,                        border: Border.all(                          color: selectedColor == color                              ? Colors.black                              : Colors.transparent,                          width: 2,                        ),                      ),                    ),                  );                }).toList(),              ),            ],          ),          actions: [            TextButton(              onPressed: () => Navigator.pop(ctx),              child: const Text('Cancel'),            ),            FilledButton(              onPressed: () async {                if (nameController.text.isNotEmpty) {                  await widget.groupService.createGroup(                    nameController.text,                    colorValue: selectedColor.value,                  );                  _refresh();                  if (mounted) Navigator.pop(ctx);                }              },              child: const Text('Create'),            ),          ],        ),      ),    );  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Contact Groups'),        actions: [          IconButton(            icon: const Icon(Icons.add),            onPressed: _createGroup,          ),        ],      ),      body: ListView.builder(        itemCount: _groups.length,        itemBuilder: (context, index) {          final group = _groups[index];          return _GroupCard(            group: group,            contacts: widget.contacts,            onRefresh: _refresh,            groupService: widget.groupService,            contactService: widget.contactService,          );        },      ),    );  }}class _GroupCard extends StatelessWidget {  final ContactGroupModel group;  final List<Contact> contacts;  final VoidCallback onRefresh;  final ContactGroupService groupService;  final ContactService contactService;  const _GroupCard({    required this.group,    required this.contacts,    required this.onRefresh,    required this.groupService,    required this.contactService,  });  IconData _getIcon() {    switch (group.iconName) {      case 'family_restroom':        return Icons.family_restroom;      case 'groups':        return Icons.groups;      case 'emergency':        return Icons.emergency;      case 'work':        return Icons.work;      default:        return Icons.folder;    }  }  List<Contact> _getGroupContacts() {    return contacts.where((c) => group.memberIds.contains(c.deviceId)).toList();  }  @override  Widget build(BuildContext context) {    final groupContacts = _getGroupContacts();    final color = Color(group.colorValue);    return Card(      margin: const EdgeInsets.all(8),      child: ExpansionTile(        leading: CircleAvatar(          backgroundColor: color.withOpacity(0.2),          child: Icon(_getIcon(), color: color),        ),        title: Text(group.name),        subtitle: Text('${groupContacts.length} members'),        children: [          if (groupContacts.isNotEmpty)            ...groupContacts.map((c) => ListTile(                  leading: CircleAvatar(child: Text(c.name[0])),                  title: Text(c.name),                  trailing: IconButton(                    icon: const Icon(Icons.remove_circle_outline),                    onPressed: () async {                      await groupService.removeContactFromGroup(                          group.name, c.deviceId);                      onRefresh();                    },                  ),                )),          Padding(            padding: const EdgeInsets.all(8.0),            child: Row(              mainAxisAlignment: MainAxisAlignment.spaceEvenly,              children: [                TextButton.icon(                  onPressed: () => _addContact(context),                  icon: const Icon(Icons.person_add),                  label: const Text('Add'),                ),                TextButton.icon(                  onPressed: groupContacts.isNotEmpty                      ? () => _sendBroadcast(context)                      : null,                  icon: const Icon(Icons.send),                  label: const Text('Broadcast'),                ),                if (!group.isSystem)                  TextButton.icon(                    onPressed: () async {                      await groupService.deleteGroup(group);                      onRefresh();                    },                    icon: const Icon(Icons.delete, color: Colors.red),                    label: const Text('Delete',                        style: TextStyle(color: Colors.red)),                  ),              ],            ),          ),        ],      ),    );  }  Future<void> _addContact(BuildContext ctx) async {    final available =        contacts.where((c) => !group.memberIds.contains(c.deviceId)).toList();    if (available.isEmpty) {      ScaffoldMessenger.of(ctx).showSnackBar(        const SnackBar(content: Text('No more contacts to add')),      );      return;    }    final selected = await showDialog<String>(      context: ctx,      builder: (dialogCtx) => SimpleDialog(        title: Text('Add to ${group.name}'),        children: available            .map((c) => SimpleDialogOption(                  onPressed: () => Navigator.pop(dialogCtx, c.deviceId),                  child: ListTile(                    leading: CircleAvatar(child: Text(c.name[0])),                    title: Text(c.name),                  ),                ))            .toList(),      ),    );    if (selected != null) {      await groupService.addContactToGroup(group.name, selected);      onRefresh();    }  }  Future<void> _sendBroadcast(BuildContext ctx) async {    final msgController = TextEditingController();    final result = await showDialog<String>(      context: ctx,      builder: (dialogCtx) => AlertDialog(        title: Text('Broadcast to ${group.name}'),        content: TextField(          controller: msgController,          decoration: const InputDecoration(            hintText: 'Enter message...',          ),          maxLines: 3,        ),        actions: [          TextButton(            onPressed: () => Navigator.pop(dialogCtx),            child: const Text('Cancel'),          ),          FilledButton(            onPressed: () => Navigator.pop(dialogCtx, msgController.text),            child: const Text('Send'),          ),        ],      ),    );    if (result != null && result.isNotEmpty) {      await groupService.sendBroadcastToGroup(group.name, result);      if (ctx.mounted) {        ScaffoldMessenger.of(ctx).showSnackBar(          SnackBar(content: Text('Broadcast sent to ${group.name}')),        );      }    }  }}